package android.net;public class NetworkCapabilities {public static final int TRANSPORT_WIFI=1,TRANSPORT_ETHERNET=3,TRANSPORT_CELLULAR=0,TRANSPORT_VPN=4,NET_CAPABILITY_NOT_VPN=15;public final int transport;public NetworkCapabilities(){transport=1;}public NetworkCapabilities(int t){transport=t;}public boolean hasCapability(int n){return n==NET_CAPABILITY_NOT_VPN&&transport!=TRANSPORT_VPN;}public boolean hasTransport(int t){return transport==t;}}
